class Base {
public:
  // User-declared destructor suppresses generation of move operations.
  virtual ~Base() = default;

  // Base is now copyable but not movable.
};

class ResourceOwner {
public:
  // User-declared copy constructor also suppresses move operations.
  ResourceOwner(const ResourceOwner& other) { /* ... */ }
private:
  int* data_;
};

// std::is_move_constructible_v<Base> is false.
// std::is_move_constructible_v<ResourceOwner> is false.
